def binary_search(nums: list[int], target: int) -> int:
    """在升序列表 nums 中查找 target。

    命中时返回某个匹配元素的下标，未命中返回 -1。
    列表必须事先按升序排列，否则比较结果没有意义。
    """
    low = 0
    high = len(nums) - 1

    while low <= high:
        mid = (low + high) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            low = mid + 1
        else:
            high = mid - 1

    return -1

from binary_search import binary_search
from trace_search import trace_binary_search

DATA = [1, 3, 5, 7, 9, 11]


def describe(nums: list[int], target: int) -> str:
    index = binary_search(nums, target)
    return str(nums) + " 查找 " + str(target) + " -> 索引 " + str(index)


def main() -> None:
    print(describe(DATA, 7))
    print(describe(DATA, 2))
    print(describe([], 5))

    print("追踪目标 7 的搜索过程：")
    for line in trace_binary_search(DATA, 7):
        print(line)


if __name__ == "__main__":
    main()
